<?php
namespace App\Services;
use App\Models\NumberGenerator; use Illuminate\Support\Facades\DB; use Illuminate\Support\Carbon;
class NumberGeneratorService { public function create(string $companyId,array $data):NumberGenerator{return DB::transaction(fn()=>NumberGenerator::create([...$data,'company_id'=>$companyId]));} public function update(NumberGenerator $generator,array $data):NumberGenerator{return DB::transaction(function()use($generator,$data){$generator->update($data);return $generator->refresh();});} public function delete(NumberGenerator $generator):void{DB::transaction(fn()=>$generator->delete());} public function next(NumberGenerator $generator):string{return DB::transaction(fn()=> $this->nextLocked($generator->fresh()));} public function nextForCompany(string $companyId,string $documentType,string $prefix='PAY'):string{$generator=NumberGenerator::query()->where('company_id',$companyId)->where('document_type',$documentType)->where('aktif',true)->lockForUpdate()->first();if(!$generator){$generator=NumberGenerator::create(['company_id'=>$companyId,'document_type'=>$documentType,'prefix'=>$prefix,'format'=>'{PREFIX}-{YYYY}{MM}-{SEQUENCE}','reset_period'=>'monthly','current_sequence'=>0,'aktif'=>true]);$generator=$generator->fresh();}return $this->nextLocked($generator);} private function nextLocked(NumberGenerator $generator):string{$now=Carbon::now();$period=$generator->reset_period==='monthly'?$now->startOfMonth():($generator->reset_period==='yearly'?$now->startOfYear():null);if($period && (!$generator->sequence_period || !$generator->sequence_period->equalTo($period))){$generator->current_sequence=0;$generator->sequence_period=$period;}$generator->current_sequence++;$generator->save();$sequence=str_pad((string)$generator->current_sequence,4,'0',STR_PAD_LEFT);return str_replace(['{PREFIX}','{YYYY}','{MM}','{SEQUENCE}'],[$generator->prefix,$now->format('Y'),$now->format('m'),$sequence],$generator->format);}}
